INSERT INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4f54-73be-8bdc-f360c89a508e', 'home', 'hero', 'repeater', '{\"en\":\"Learn German. Build Your Path to Germany.\",\"de\":\"Deutsch lernen. Ihren Weg nach Deutschland gestalten.\",\"ne\":\"जर्मन भाषा सिक्नुहोस्। जर्मनीतिर आफ्नो बाटो बनाउनुहोस्।\"}', '{\"de\":null}', '{\"en\":\"<p>Start your German language journey with Himalayan Education Pathways, your destination for structured German language classes in Chabahil, Kathmandu.</p><p>Learn German from A1 to B2 through practical lessons focused on speaking, listening, reading, writing, grammar and vocabulary.</p><p>Whether you\'re learning German for Ausbildung, higher education, career opportunities, examinations or life in Germany, start building your language skills with us.</p>\",\"de\":\"<p>Beginnen Sie Ihre Reise in die deutsche Sprache bei Himalayan Education Pathways, Ihrem Ort für strukturierte Deutschkurse in Chabahil, Kathmandu.</p><p>Lernen Sie Deutsch von A1 bis B2 in praxisnahen Lektionen, die sich auf Sprechen, Hören, Lesen, Schreiben, Grammatik und Wortschatz konzentrieren.</p><p>Ob Sie Deutsch für eine Ausbildung, ein Studium, berufliche Chancen, Prüfungen oder das Leben in Deutschland lernen – beginnen Sie mit uns, Ihre Sprachkenntnisse aufzubauen.</p>\",\"ne\":\"<p>Himalayan Education Pathways मार्फत आफ्नो जर्मन भाषा यात्रा सुरु गर्नुहोस्, जुन चावहिल, काठमाडौंमा व्यवस्थित जर्मन भाषा कक्षाहरूको गन्तव्य हो।</p><p>बोल्ने, सुन्ने, पढ्ने, लेख्ने, व्याकरण र शब्दावलीमा केन्द्रित व्यावहारिक कक्षाहरूमार्फत A1 देखि B2 सम्म जर्मन सिक्नुहोस्।</p><p>तपाईं Ausbildung, उच्च शिक्षा, करियर अवसर, परीक्षा वा जर्मनीमा जीवनका लागि जर्मन सिक्दै हुनुहुन्छ भने, हामीसँग आफ्नो भाषिक सीप निर्माण गर्न आजै सुरु गर्नुहोस्।</p>\"}', '{\"primary_cta\":\"Explore Courses\",\"secondary_cta\":\"Enroll Now\"}', 1, 1, '2026-10-02 10:16:14', '2026-10-04 06:21:30', NULL);
INSERT INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4f5a-72e4-80be-8938ee0ed2a8', 'home', 'stats', 'cards', '{\"en\":\"Home Statistics\",\"ne\":\"गृहपृष्ठ तथ्याङ्क\",\"de\":\"Statistiken der Startseite\"}', '{\"de\":null}', '{\"de\":null}', '[]', 1, 2, '2026-10-02 10:16:14', '2026-10-04 06:36:42', NULL);
INSERT INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4f78-7358-8b92-8ee4c726ccea', 'home', 'journey', 'repeater', '{\"en\":\"Start Your German Learning Journey With Us\",\"de\":\"Beginnen Sie mit uns Ihre Deutschlernreise\",\"ne\":\"हामीसँग जर्मन सिकाइ यात्रा सुरु गर्नुहोस्\"}', NULL, '{\"en\":\"<p>Learning a new language opens doors to new cultures, education and professional opportunities. At Himalayan Education Pathways, we provide structured German language education designed to help learners progress confidently from beginner to upper-intermediate levels.</p>\",\"de\":\"<p>Eine neue Sprache öffnet die Tür zu neuen Kulturen, Bildungswegen und beruflichen Möglichkeiten. Bei Himalayan Education Pathways bieten wir eine strukturierte Deutschausbildung, mit der Lernende sicher von den Anfängen bis zum gehobenen Mittelstufenniveau vorankommen.</p>\",\"ne\":\"<p>नयाँ भाषा सिक्दा नयाँ संस्कृति, शिक्षा र व्यावसायिक अवसरहरूको ढोका खुल्छ। Himalayan Education Pathways मा हामी व्यवस्थित जर्मन भाषा शिक्षा प्रदान गर्छौं, जसले सिक्नेहरूलाई शुरुवातीदेखि माथिल्लो-मध्यम स्तरसम्म आत्मविश्वासका साथ अघि बढ्न मद्दत गर्छ।</p>\"}', NULL, 1, 3, '2026-10-02 10:16:14', '2026-10-03 16:25:28', NULL);
INSERT INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4f8b-7042-a551-891c70355318', 'home', 'about', 'single_block', '{\"en\":\"Learn German in Kathmandu With Himalayan Education Pathways\",\"de\":\"Deutsch lernen in Kathmandu mit Himalayan Education Pathways\",\"ne\":\"Himalayan Education Pathways सँग काठमाडौंमा जर्मन सिक्नुहोस्\"}', NULL, '{\"en\":\"<p>Himalayan Education Pathways is a German language institute located in Chabahil, Kathmandu, providing structured language education from beginner A1 through B2. Our courses are designed to develop practical communication alongside grammar, vocabulary, pronunciation, listening, reading and writing. Whether you are preparing for a German language examination, Ausbildung, higher education, professional opportunities or everyday life in Germany, we provide a structured path for improving your German.</p>\",\"de\":\"<p>Himalayan Education Pathways ist ein Institut für Deutschausbildung in Chabahil, Kathmandu, das strukturierte Sprachausbildung von A1 bis B2 anbietet. Unsere Kurse entwickeln praktische Kommunikationsfähigkeit zusammen mit Grammatik, Wortschatz, Aussprache, Hörverstehen, Leseverstehen und Schreiben. Ob Sie sich auf eine Deutschprüfung, eine Ausbildung, ein Studium, berufliche Chancen oder den Alltag in Deutschland vorbereiten – wir bieten Ihnen einen strukturierten Weg, Ihr Deutsch zu verbessern.</p>\",\"ne\":\"<p>Himalayan Education Pathways चावहिल, काठमाडौंमा रहेको जर्मन भाषा शिक्षा संस्था हो, जसले शुरुवाती A1 देखि B2 सम्म व्यवस्थित भाषा शिक्षा प्रदान गर्छ। हाम्रा कोर्सहरू व्याकरण, शब्दावली, उच्चारण, सुनाइ, पढाइ र लेखाइसँगै व्यावहारिक सञ्चार सीप विकास गर्न डिजाइन गरिएका छन्। तपाईं जर्मन परीक्षा, Ausbildung, उच्च शिक्षा, व्यावसायिक अवसर वा जर्मनीमा दैनिक जीवनका लागि तयारी गर्दै हुनुहुन्छ भने, हामी तपाईंको जर्मन सुधार्न व्यवस्थित बाटो प्रदान गर्छौं।</p>\"}', '{\"cta\":\"Explore All Courses\"}', 1, 4, '2026-10-02 10:16:14', '2026-10-03 16:25:28', NULL);
INSERT INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4fa7-726a-b711-79112d16e1e9', 'home', 'popular-categories', 'cards', '{\"en\":\"Explore Our German Learning Programs\",\"de\":\"Entdecken Sie unsere Deutschprogramme\",\"ne\":\"हाम्रा जर्मन सिकाइ कार्यक्रमहरू हेर्नुहोस्\"}', NULL, '{\"en\":\"<p>Choose the learning path that matches your current German level and future goals.</p>\",\"de\":\"<p>Wählen Sie den Lernweg, der zu Ihrem aktuellen Deutschniveau und Ihren Zielen passt.</p>\",\"ne\":\"<p>तपाईंको हालको जर्मन स्तर र भविष्यका लक्ष्यसँग मेल खाने सिकाइ मार्ग छान्नुहोस्।</p>\"}', NULL, 1, 5, '2026-10-02 10:16:14', '2026-10-03 16:25:28', NULL);
INSERT INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4fc5-7143-b349-1a2c76151477', 'home', 'why-choose-us', 'cards', '{\"en\":\"Why Choose Himalayan Education Pathways for German Classes?\",\"de\":\"Warum Himalayan Education Pathways für Ihre Deutschkurse?\",\"ne\":\"जर्मन कक्षाका लागि Himalayan Education Pathways किन छान्ने?\"}', NULL, '{\"en\":\"<p>Learning German requires consistency, practical communication and a clear progression from one language level to another. Our programs are structured to help learners gradually build confidence while developing all four essential language skills.</p>\",\"de\":\"<p>Deutsch zu lernen erfordert Beständigkeit, praxisnahe Kommunikation und einen klaren Fortschritt von einem Sprachniveau zum nächsten. Unsere Programme sind so aufgebaut, dass Lernende schrittweise Selbstvertrauen gewinnen und dabei alle vier wichtigen Sprachfertigkeiten entwickeln.</p>\",\"ne\":\"<p>जर्मन सिक्न निरन्तरता, व्यावहारिक सञ्चार र एउटा स्तरबाट अर्को स्तरमा स्पष्ट प्रगति चाहिन्छ। हाम्रा कार्यक्रमहरू सिक्नेहरूले चारै आधारभूत भाषिक सीप विकास गर्दै बिस्तारै आत्मविश्वास बढाउन सक्ने गरी संरचित छन्।</p>\"}', '{\"cta\":\"View All Courses\"}', 1, 6, '2026-10-02 10:16:14', '2026-10-03 16:25:28', NULL);
INSERT INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4fdf-73cf-b0e1-8f6b9562c9d7', 'home', 'leadership', 'repeater', '{\"en\":\"Meet Our Leadership\",\"de\":\"Lernen Sie unsere Leitung kennen\",\"ne\":\"हाम्रो नेतृत्वसँग परिचित हुनुहोस्\"}', NULL, '{\"en\":\"<p>Meet the people guiding Himalayan Education Pathways and its commitment to quality German language education.</p>\",\"de\":\"<p>Lernen Sie die Menschen kennen, die Himalayan Education Pathways leiten und sich für hochwertige Deutschausbildung einsetzen.</p>\",\"ne\":\"<p>Himalayan Education Pathways लाई मार्गदर्शन गर्ने र गुणस्तरीय जर्मन भाषा शिक्षाप्रति प्रतिबद्ध व्यक्तित्वहरूलाई भेट्नुहोस्।</p>\"}', NULL, 1, 7, '2026-10-02 10:16:14', '2026-10-03 16:25:28', NULL);
INSERT INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4fe9-71ae-91cb-4225e4c03e4b', 'home', 'testimonials', 'repeater', '{\"en\":\"What Our Students Say\",\"de\":\"Was unsere Studierenden sagen\",\"ne\":\"हाम्रा विद्यार्थीहरू के भन्छन्\"}', NULL, '{\"en\":null}', NULL, 1, 8, '2026-10-02 10:16:14', '2026-10-02 10:16:14', NULL);
INSERT INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4ff6-73c9-bfe7-c87df62b33f4', 'home', 'career-cta', 'single_block', '{\"en\":\"Planning Your Future in Germany?\",\"de\":\"Ihre Zukunft in Deutschland planen?\",\"ne\":\"जर्मनीमा आफ्नो भविष्य योजना बनाउँदै हुनुहुन्छ?\"}', NULL, '{\"en\":\"<p>Build the German language foundation required for your future plans.</p><p>Whether your goal is Ausbildung, higher education, professional development or everyday communication, start your German journey with structured language learning.</p>\",\"de\":\"<p>Bauen Sie die sprachlichen Grundlagen auf, die Ihre Zukunftspläne erfordern.</p><p>Ob Ihr Ziel Ausbildung, Studium, berufliche Weiterentwicklung oder alltägliche Kommunikation ist – beginnen Sie Ihre Deutschreise mit strukturiertem Sprachunterricht.</p>\",\"ne\":\"<p>तपाईंका भविष्यका योजनाहरूका लागि आवश्यक जर्मन भाषाको आधार निर्माण गर्नुहोस्।</p><p>तपाईंको लक्ष्य Ausbildung, उच्च शिक्षा, व्यावसायिक विकास वा दैनिक सञ्चार जुनसुकै भए पनि, व्यवस्थित भाषा सिकाइसँग आफ्नो जर्मन यात्रा सुरु गर्नुहोस्।</p>\"}', '{\"cta\":\"Explore German Courses\"}', 1, 9, '2026-10-02 10:16:14', '2026-10-03 16:25:28', NULL);
INSERT INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-4ff9-7228-b147-3ee4afd7deee', 'about', 'about-intro', 'single_block', '{\"en\":\"Start Your German Journey With Us\",\"de\":\"Beginnen Sie Ihre Deutschreise mit uns\",\"ne\":\"हामीसँग आफ्नो जर्मन यात्रा सुरु गर्नुहोस्\"}', NULL, '{\"en\":\"<p>Himalayan Education Pathways is a German language education institute located in Chabahil–7, Kathmandu, Nepal. Our goal is to provide structured, practical and accessible German language education to learners preparing for academic, professional and personal opportunities. From complete beginners starting A1 to learners progressing through A2, B1 and B2, our courses focus on building confidence across speaking, listening, reading and writing.</p>\",\"de\":\"<p>Himalayan Education Pathways ist ein Institut für Deutschausbildung in Chabahil–7, Kathmandu, Nepal. Unser Ziel ist es, Lernenden, die sich auf akademische, berufliche und persönliche Chancen vorbereiten, strukturierte, praxisnahe und zugängliche Deutschausbildung zu bieten. Von kompletten Anfängern auf A1 bis zu Lernenden auf dem Weg über A2, B1 und B2 konzentrieren sich unsere Kurse darauf, Selbstvertrauen im Sprechen, Hören, Lesen und Schreiben aufzubauen.</p>\",\"ne\":\"<p>Himalayan Education Pathways चावहिल–७, काठमाडौं, नेपालमा रहेको जर्मन भाषा शिक्षा संस्था हो। हाम्रो लक्ष्य शैक्षिक, व्यावसायिक र व्यक्तिगत अवसरका लागि तयारी गर्ने सिकाइकर्ताहरूलाई व्यवस्थित, व्यावहारिक र सुलभ जर्मन भाषा शिक्षा प्रदान गर्नु हो। A1 मा पूर्ण शुरुवातीदेखि A2, B1 र B2 सम्म प्रगति गर्ने सिकाइकर्ताहरूका लागि हाम्रा कोर्सहरूले बोलाइ, सुनाइ, पढाइ र लेखाइमा आत्मविश्वास निर्माण गर्नमा केन्द्रित छन्।</p>\"}', NULL, 1, 1, '2026-10-02 10:16:14', '2026-10-03 16:25:28', NULL);
INSERT INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-5014-7120-aef4-ec3ccaac726e', 'about', 'about-mission-vision', 'cards', '{\"en\":\"Our Mission & Vision\",\"de\":\"Unsere Mission & Vision\",\"ne\":\"हाम्रो मिसन र भिजन\"}', NULL, '{\"en\":null}', NULL, 1, 2, '2026-10-02 10:16:14', '2026-10-02 10:16:14', NULL);
