INSERT INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-5039-7320-a4c4-9bdf3e1f5c50', 'about', 'about-stats', 'repeater', '{\"en\":\"About Page Statistics\",\"de\":\"Statistiken der Über-uns-Seite\",\"ne\":\"हाम्रो बारेमा पृष्ठको तथ्याङ्क\"}', NULL, '{\"en\":null}', NULL, 1, 4, '2026-10-02 10:16:14', '2026-10-02 10:16:14', NULL);
INSERT INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-504d-7091-a169-9f383e3605b6', 'about', 'career-cta', 'single_block', '{\"en\":\"Planning Your Future in Germany?\",\"de\":\"Ihre Zukunft in Deutschland planen?\",\"ne\":\"जर्मनीमा आफ्नो भविष्य योजना बनाउँदै हुनुहुन्छ?\"}', NULL, '{\"en\":\"<p>Build the German language foundation required for your future plans.</p><p>Whether your goal is Ausbildung, higher education, professional development or everyday communication, start your German journey with structured language learning.</p>\",\"de\":\"<p>Bauen Sie die sprachlichen Grundlagen auf, die Ihre Zukunftspläne erfordern.</p><p>Ob Ihr Ziel Ausbildung, Studium, berufliche Weiterentwicklung oder alltägliche Kommunikation ist – beginnen Sie Ihre Deutschreise mit strukturiertem Sprachunterricht.</p>\",\"ne\":\"<p>तपाईंका भविष्यका योजनाहरूका लागि आवश्यक जर्मन भाषाको आधार निर्माण गर्नुहोस्।</p><p>तपाईंको लक्ष्य Ausbildung, उच्च शिक्षा, व्यावसायिक विकास वा दैनिक सञ्चार जुनसुकै भए पनि, व्यवस्थित भाषा सिकाइसँग आफ्नो जर्मन यात्रा सुरु गर्नुहोस्।</p>\"}', '{\"cta\":\"Explore German Courses\"}', 1, 5, '2026-10-02 10:16:14', '2026-10-03 16:25:28', NULL);
INSERT INTO `sections` (`id`, `page_slug`, `key`, `layout_type`, `title`, `subtitle`, `content`, `settings`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-5050-71a3-92bc-5a7ac3d25719', 'faq', 'faq-list', 'repeater', '{\"en\":\"Frequently Asked Questions\",\"de\":\"Häufig gestellte Fragen\",\"ne\":\"बारम्बार सोधिने प्रश्नहरू\"}', NULL, '{\"en\":null}', NULL, 1, 1, '2026-10-02 10:16:14', '2026-10-04 06:21:04', NULL);
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-4f7c-709b-a0b3-2e649a02907f', '01a0fc1d-4f78-7358-8b92-8ee4c726ccea', '{\"en\":\"Experienced Guidance\",\"de\":\"Erfahrene Begleitung\",\"ne\":\"अनुभवी मार्गदर्शन\"}', '{\"en\":\"<p>Learn German through structured lessons with guidance designed to make grammar, vocabulary and communication easier to understand.</p>\",\"de\":\"<p>Lernen Sie Deutsch in strukturierten Lektionen mit einer Begleitung, die Grammatik, Wortschatz und Kommunikation leichter verständlich macht.</p>\",\"ne\":\"<p>व्यवस्थित पाठहरू र व्याकरण, शब्दावली तथा सञ्चार सजिलै बुझ्न मद्दत गर्ने मार्गदर्शनमार्फत जर्मन सिक्नुहोस्।</p>\"}', '01', NULL, 1, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-4f80-72a4-b93d-71c591263b8a', '01a0fc1d-4f78-7358-8b92-8ee4c726ccea', '{\"en\":\"Quality Education\",\"de\":\"Qualitativ hochwertige Ausbildung\",\"ne\":\"गुणस्तरीय शिक्षा\"}', '{\"en\":\"<p>Develop speaking, listening, reading and writing skills through a balanced and progressive learning approach.</p>\",\"de\":\"<p>Entwickeln Sie Sprech-, Hör-, Lese- und Schreibfertigkeiten durch einen ausgewogenen und schrittweisen Lernansatz.</p>\",\"ne\":\"<p>सन्तुलित र क्रमिक सिकाइ विधिमार्फत बोल्ने, सुन्ने, पढ्ने र लेख्ने सीप विकास गर्नुहोस्।</p>\"}', '02', NULL, 2, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
