INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-4faf-72c1-b874-2e9ae77987ef', '01a0fc1d-4fa7-726a-b711-79112d16e1e9', '{\"en\":\"German A2\",\"de\":\"Deutsch A2\",\"ne\":\"जर्मन A2\"}', '{\"en\":\"<p>Expand your basic German skills and communicate more confidently in familiar everyday situations.</p>\",\"de\":\"<p>Erweitern Sie Ihre Grundkenntnisse im Deutschen und kommunizieren Sie in vertrauten Alltagssituationen selbstbewusster.</p>\",\"ne\":\"<p>तपाईंको आधारभूत जर्मन सीप विस्तार गर्नुहोस् र परिचित दैनिक परिस्थितिहरूमा अझ आत्मविश्वासका साथ सञ्चार गर्नुहोस्।</p>\"}', NULL, NULL, 2, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
