INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-4fb5-7108-9b6a-ac1261d2866c', '01a0fc1d-4fa7-726a-b711-79112d16e1e9', '{\"en\":\"German B2\",\"de\":\"Deutsch B2\",\"ne\":\"जर्मन B2\"}', '{\"en\":\"<p>Build stronger fluency and communicate confidently about more complex academic, professional and everyday topics.</p>\",\"de\":\"<p>Stärken Sie Ihre Sprachsicherheit und kommunizieren Sie souverän über anspruchsvollere akademische, berufliche und alltägliche Themen.</p>\",\"ne\":\"<p>धाराप्रवाहता बलियो बनाउनुहोस् र थप जटिल शैक्षिक, व्यावसायिक र दैनिक विषयहरूमा आत्मविश्वासका साथ कुरा गर्नुहोस्।</p>\"}', NULL, NULL, 4, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
