INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-4fd9-7100-b377-256b0d7f8fee', '01a0fc1d-4fc5-7143-b349-1a2c76151477', '{\"en\":\"Convenient Location\",\"de\":\"Günstige Lage\",\"ne\":\"सुविधाजनक स्थान\"}', '{\"en\":\"<p>Attend German language classes conveniently in Chabahil, Kathmandu.</p>\",\"de\":\"<p>Besuchen Sie Deutschkurse bequem in Chabahil, Kathmandu.</p>\",\"ne\":\"<p>चावहिल, काठमाडौंमा सुविधाजनक रूपमा जर्मन भाषा कक्षाहरूमा भाग लिनुहोस्।</p>\"}', NULL, NULL, 5, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-4fdd-71fc-8237-6511ed4517d4', '01a0fc1d-4fc5-7143-b349-1a2c76151477', '{\"en\":\"Balanced Language Skills\",\"de\":\"Ausgewogene Sprachfertigkeiten\",\"ne\":\"सन्तुलित भाषिक सीप\"}', '{\"en\":\"<p>Develop speaking, listening, reading and writing alongside grammar and vocabulary.</p>\",\"de\":\"<p>Entwickeln Sie Sprechen, Hören, Lesen und Schreiben zusammen mit Grammatik und Wortschatz.</p>\",\"ne\":\"<p>व्याकरण र शब्दावलीसँगै बोल्ने, सुन्ने, पढ्ने र लेख्ने सीप विकास गर्नुहोस्।</p>\"}', NULL, NULL, 6, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-4fe3-7363-a34d-b7110ef64384', '01a0fc1d-4fdf-73cf-b0e1-8f6b9562c9d7', '{\"en\":\"Jeevan Thakuri\"}', '{\"en\":\"<p>Committed to building an accessible and supportive German learning environment for students preparing for education, career and personal opportunities.</p>\",\"de\":\"<p>Engagiert für den Aufbau einer zugänglichen und unterstützenden Lernumgebung für Deutsch, für Studierende, die sich auf Bildung, Karriere und persönliche Chancen vorbereiten.</p>\",\"ne\":\"<p>शिक्षा, करियर र व्यक्तिगत अवसरका लागि तयारी गर्ने विद्यार्थीहरूका लागि सुलभ र सहयोगी जर्मन सिकाइ वातावरण निर्माणमा प्रतिबद्ध।</p>\"}', 'Chief Executive Officer', NULL, 1, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-4fe6-72e0-abc7-1c72795997cb', '01a0fc1d-4fdf-73cf-b0e1-8f6b9562c9d7', '{\"en\":\"Gaurav Jung Shah\"}', '{\"en\":\"<p>Focused on providing students with structured learning, practical guidance and a positive environment throughout their German language journey.</p>\",\"de\":\"<p>Ausgerichtet auf strukturiertes Lernen, praktische Begleitung und ein positives Umfeld auf dem gesamten Weg der Deutschlernenden.</p>\",\"ne\":\"<p>जर्मन भाषा यात्राभर विद्यार्थीहरूलाई व्यवस्थित सिकाइ, व्यावहारिक मार्गदर्शन र सकारात्मक वातावरण प्रदान गर्नमा केन्द्रित।</p>\"}', 'Managing Director', NULL, 2, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-4fec-726f-86c1-9206b5d844f8', '01a0fc1d-4fe9-71ae-91cb-4225e4c03e4b', '{\"en\":\"Sample Student — German A1\",\"de\":\"Beispiel-Studierende/r — Deutsch A1\",\"ne\":\"नमुना विद्यार्थी — जर्मन A1\"}', '{\"en\":\"<p>The classes helped me understand German grammar much more clearly. Regular speaking practice also made me more confident using the language.</p>\",\"de\":\"<p>Der Unterricht hat mir geholfen, die deutsche Grammatik viel klarer zu verstehen. Das regelmäßige Sprechtraining hat mich außerdem sicherer im Gebrauch der Sprache gemacht.</p>\",\"ne\":\"<p>कक्षाले मलाई जर्मन व्याकरण धेरै स्पष्ट रूपमा बुझ्न मद्दत गर्‍यो। नियमित बोलाइ अभ्यासले भाषा प्रयोग गर्न पनि मलाई थप आत्मविश्वासी बनायो।</p>\"}', NULL, NULL, 1, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-4fef-7089-b63c-69aeac5c3ef0', '01a0fc1d-4fe9-71ae-91cb-4225e4c03e4b', '{\"en\":\"Sample Student — German B1\",\"de\":\"Beispiel-Studierende/r — Deutsch B1\",\"ne\":\"नमुना विद्यार्थी — जर्मन B1\"}', '{\"en\":\"<p>The lessons were structured and easy to follow. The speaking and writing practice helped me understand where I needed to improve.</p>\",\"de\":\"<p>Der Unterricht war gut strukturiert und leicht nachvollziehbar. Das Sprech- und Schreibtraining hat mir gezeigt, wo ich mich noch verbessern muss.</p>\",\"ne\":\"<p>पाठहरू व्यवस्थित र सजिलै पछ्याउन सकिने थिए। बोलाइ र लेखाइ अभ्यासले मलाई कहाँ सुधार गर्नुपर्ने हो भन्ने बुझ्न मद्दत गर्‍यो।</p>\"}', NULL, NULL, 2, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-4ff2-7024-9100-7ecab0cebbcd', '01a0fc1d-4fe9-71ae-91cb-4225e4c03e4b', '{\"en\":\"Sample Student — Ausbildung Preparation\",\"de\":\"Beispiel-Studierende/r — Ausbildungsvorbereitung\",\"ne\":\"नमुना विद्यार्थी — Ausbildung तयारी\"}', '{\"en\":\"<p>I wanted a clear learning path for German instead of studying randomly by myself. The classes helped me progress step by step.</p>\",\"de\":\"<p>Ich wollte einen klaren Lernweg für Deutsch, statt allein und planlos zu lernen. Der Unterricht hat mir geholfen, Schritt für Schritt voranzukommen.</p>\",\"ne\":\"<p>मलाई एक्लै अव्यवस्थित रूपमा पढ्नुभन्दा जर्मनका लागि स्पष्ट सिकाइ मार्ग चाहिएको थियो। कक्षाले मलाई चरणबद्ध रूपमा अघि बढ्न मद्दत गर्‍यो।</p>\"}', NULL, NULL, 3, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-4ffc-72b5-8d5a-93a79a907bf9', '01a0fc1d-4ff9-7228-b147-3ee4afd7deee', '{\"en\":\"German A1–B2 courses\",\"de\":\"Deutschkurse A1–B2\",\"ne\":\"A1–B2 जर्मन कोर्सहरू\"}', '{\"en\":null}', NULL, NULL, 1, '2026-10-02 10:16:14', '2026-10-02 10:16:14');
