INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-500a-73bf-969b-b0e2672422a7', '01a0fc1d-4ff9-7228-b147-3ee4afd7deee', '{\"en\":\"Ausbildung-focused German preparation\",\"de\":\"Auf die Ausbildung ausgerichtete Deutschvorbereitung\",\"ne\":\"Ausbildung-केन्द्रित जर्मन तयारी\"}', '{\"en\":null}', NULL, NULL, 5, '2026-10-02 10:16:14', '2026-10-02 10:16:14');
