INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5017-7334-80c5-3ef8d6c3ebd9', '01a0fc1d-5014-7120-aef4-ec3ccaac726e', '{\"en\":\"Our Mission\",\"de\":\"Unsere Mission\",\"ne\":\"हाम्रो मिसन\"}', '{\"en\":\"<p>To provide structured and practical German language education that helps learners develop the communication skills and confidence required to pursue their academic, professional and personal goals.</p>\",\"de\":\"<p>Praktische und strukturierte Deutschausbildung anzubieten, die Lernenden die Kommunikationsfähigkeit und das Selbstvertrauen vermittelt, um ihre akademischen, beruflichen und persönlichen Ziele zu verfolgen.</p>\",\"ne\":\"<p>सिक्नेहरूलाई शैक्षिक, व्यावसायिक र व्यक्तिगत लक्ष्य प्राप्त गर्न आवश्यक सञ्चार सीप र आत्मविश्वास दिने व्यावहारिक र व्यवस्थित जर्मन भाषा शिक्षा प्रदान गर्नु।</p>\"}', NULL, NULL, 1, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-501b-701a-b169-188d8e9a9c3e', '01a0fc1d-5014-7120-aef4-ec3ccaac726e', '{\"en\":\"Our Vision\",\"de\":\"Unsere Vision\",\"ne\":\"हाम्रो भिजन\"}', '{\"en\":\"<p>To become a trusted destination for German language education in Nepal by creating an effective, supportive and student-focused learning environment.</p>\",\"de\":\"<p>Eine vertrauenswürdige Adresse für Deutschausbildung in Nepal werden, mit einem wirksamen, unterstützenden und lernendenorientierten Lernumfeld.</p>\",\"ne\":\"<p>प्रभावकारी, सहयोगी र विद्यार्थी-केन्द्रित सिकाइ वातावरण निर्माण गरेर नेपालमा जर्मन भाषा शिक्षाका लागि विश्वसनीय गन्तव्य बन्नु।</p>\"}', NULL, NULL, 2, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5020-7362-bb1a-70dc3a28c04e', '01a0fc1d-501d-7345-b599-947a2329a167', '{\"en\":\"Structured Learning\",\"de\":\"Strukturiertes Lernen\",\"ne\":\"व्यवस्थित सिकाइ\"}', '{\"en\":\"<p>Progress logically through German language levels from A1 to B2.</p>\",\"de\":\"<p>Schreiten Sie logisch durch die Deutschniveaus von A1 bis B2 voran.</p>\",\"ne\":\"<p>A1 देखि B2 सम्म जर्मन स्तरहरूमा तार्किक रूपमा अघि बढ्नुहोस्।</p>\"}', NULL, NULL, 1, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5023-73ff-be5c-f34b3ed2bc2f', '01a0fc1d-501d-7345-b599-947a2329a167', '{\"en\":\"Practical Communication\",\"de\":\"Praktische Kommunikation\",\"ne\":\"व्यावहारिक सञ्चार\"}', '{\"en\":\"<p>Apply vocabulary and grammar through speaking and real-world communication activities.</p>\",\"de\":\"<p>Wenden Sie Wortschatz und Grammatik in Sprech- und Alltagskommunikation an.</p>\",\"ne\":\"<p>बोलाइ र वास्तविक जीवनका सञ्चार क्रियाकलापमार्फत शब्दावली र व्याकरण प्रयोग गर्नुहोस्।</p>\"}', NULL, NULL, 2, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-502b-7188-8dba-b71855a56699', '01a0fc1d-501d-7345-b599-947a2329a167', '{\"en\":\"Balanced Skills\",\"de\":\"Ausgewogene Fertigkeiten\",\"ne\":\"सन्तुलित सीप\"}', '{\"en\":\"<p>Develop speaking, listening, reading and writing together.</p>\",\"de\":\"<p>Entwickeln Sie Sprechen, Hören, Lesen und Schreiben gemeinsam.</p>\",\"ne\":\"<p>बोल्ने, सुन्ने, पढ्ने र लेख्ने सीप सँगै विकास गर्नुहोस्।</p>\"}', NULL, NULL, 3, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5030-7373-8222-4301c5676827', '01a0fc1d-501d-7345-b599-947a2329a167', '{\"en\":\"Student Guidance\",\"de\":\"Begleitung der Studierenden\",\"ne\":\"विद्यार्थी मार्गदर्शन\"}', '{\"en\":\"<p>Receive consistent guidance throughout your language-learning journey.</p>\",\"de\":\"<p>Erhalten Sie kontinuierliche Begleitung auf Ihrem gesamten Sprachlernweg.</p>\",\"ne\":\"<p>तपाईंको भाषा सिकाइ यात्राभर नियमित मार्गदर्शन पाउनुहोस्।</p>\"}', NULL, NULL, 4, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-503e-7178-9631-f3d754bf7708', '01a0fc1d-5039-7320-a4c4-9bdf3e1f5c50', '{\"en\":\"4\"}', '{\"en\":\"<p>German Levels</p>\",\"de\":\"<p>Deutsche Sprachniveaus</p>\",\"ne\":\"<p>जर्मन भाषा स्तरहरू</p>\"}', NULL, NULL, 1, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5042-7174-8a88-21158f78e8ac', '01a0fc1d-5039-7320-a4c4-9bdf3e1f5c50', '{\"en\":\"A1–B2\"}', '{\"en\":\"<p>Complete Learning Path</p>\",\"de\":\"<p>Vollständiger Lernweg</p>\",\"ne\":\"<p>पूर्ण सिकाइ मार्ग</p>\"}', NULL, NULL, 2, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5045-737f-a53c-74702245f3da', '01a0fc1d-5039-7320-a4c4-9bdf3e1f5c50', '{\"en\":\"2 Hours\",\"de\":\"2 Stunden\",\"ne\":\"२ घण्टा\"}', '{\"en\":\"<p>Daily Classes</p>\",\"de\":\"<p>Tägliche Kurse</p>\",\"ne\":\"<p>दैनिक कक्षाहरू</p>\"}', NULL, NULL, 3, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5049-72b4-9943-d266597310fd', '01a0fc1d-5039-7320-a4c4-9bdf3e1f5c50', '{\"en\":\"Kathmandu\"}', '{\"en\":\"<p>Local German Learning Center</p>\",\"de\":\"<p>Lokales Deutschlernzentrum</p>\",\"ne\":\"<p>स्थानीय जर्मन सिकाइ केन्द्र</p>\"}', NULL, NULL, 4, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5054-715d-8ebe-1ee644ab9fb4', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"Where can I learn German in Kathmandu?\",\"de\":\"Wo kann ich in Kathmandu Deutsch lernen?\",\"ne\":\"काठमाडौंमा म कहाँ जर्मन सिक्न सक्छु?\"}', '{\"en\":\"<p>Himalayan Education Pathways provides German language classes from A1 to B2 at our institute in Chabahil–7, Kathmandu.</p>\",\"de\":\"<p>Himalayan Education Pathways bietet Deutschkurse von A1 bis B2 in unserem Institut in Chabahil–7, Kathmandu, an.</p>\",\"ne\":\"<p>Himalayan Education Pathways ले चावहिल–७, काठमाडौंस्थित हाम्रो संस्थामा A1 देखि B2 सम्मका जर्मन भाषा कक्षाहरू प्रदान गर्छ।</p>\"}', NULL, NULL, 1, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5057-716f-893b-11422a726dec', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"What German courses do you offer?\",\"de\":\"Welche Deutschkurse bieten Sie an?\",\"ne\":\"तपाईंहरूले कुन जर्मन कोर्सहरू दिनुहुन्छ?\"}', '{\"en\":\"<p>We currently provide German A1, A2, B1 and B2 language courses.</p>\",\"de\":\"<p>Derzeit bieten wir Deutschkurse A1, A2, B1 und B2 an.</p>\",\"ne\":\"<p>हाल हामी जर्मन A1, A2, B1 र B2 कोर्सहरू प्रदान गर्छौं।</p>\"}', NULL, NULL, 2, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-505a-7113-9068-3fdf817b45fe', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"Can complete beginners join German A1?\",\"de\":\"Können komplette Anfänger den Kurs Deutsch A1 besuchen?\",\"ne\":\"पूर्ण शुरुवातीहरू जर्मन A1 मा सहभागी हुन सक्छन्?\"}', '{\"en\":\"<p>Yes. German A1 is specifically designed for learners starting German with little or no previous knowledge.</p>\",\"de\":\"<p>Ja. Deutsch A1 ist speziell für Lernende konzipiert, die mit wenig oder keinen Vorkenntnissen beginnen.</p>\",\"ne\":\"<p>हो। जर्मन A1 थोरै वा कुनै पूर्व ज्ञान नभएका सिकाइकर्ताहरूका लागि विशेष रूपमा डिजाइन गरिएको हो।</p>\"}', NULL, NULL, 3, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-505e-7033-9bf3-3cb11619c6ac', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"How long is the German A1 course?\",\"de\":\"Wie lange dauert der Kurs Deutsch A1?\",\"ne\":\"जर्मन A1 कोर्स कति लामो छ?\"}', '{\"en\":\"<p>The A1 course runs for approximately two months with around two hours of classes per day.</p>\",\"de\":\"<p>Der Kurs A1 dauert ungefähr zwei Monate, mit etwa zwei Unterrichtsstunden pro Tag.</p>\",\"ne\":\"<p>A1 कोर्स लगभग दुई महिनाको हुन्छ, दिनमा लगभग दुई घण्टा कक्षा हुन्छन्।</p>\"}', NULL, NULL, 4, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5062-718b-addb-65675e2c9344', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"How long is German A2?\",\"de\":\"Wie lange dauert Deutsch A2?\",\"ne\":\"जर्मन A2 कति लामो छ?\"}', '{\"en\":\"<p>German A2 runs for approximately two months with around two hours of classes per day.</p>\",\"de\":\"<p>Deutsch A2 dauert ungefähr zwei Monate, mit etwa zwei Unterrichtsstunden pro Tag.</p>\",\"ne\":\"<p>जर्मन A2 लगभग दुई महिनाको हुन्छ, दिनमा लगभग दुई घण्टा कक्षा हुन्छन्।</p>\"}', NULL, NULL, 5, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5066-7336-ac31-7096415c6b2a', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"How long is German B1?\",\"de\":\"Wie lange dauert Deutsch B1?\",\"ne\":\"जर्मन B1 कति लामो छ?\"}', '{\"en\":\"<p>German B1 runs for approximately 2.5 months with around two hours of classes per day.</p>\",\"de\":\"<p>Deutsch B1 dauert ungefähr 2,5 Monate, mit etwa zwei Unterrichtsstunden pro Tag.</p>\",\"ne\":\"<p>जर्मन B1 लगभग २.५ महिनाको हुन्छ, दिनमा लगभग दुई घण्टा कक्षा हुन्छन्।</p>\"}', NULL, NULL, 6, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5069-7035-becd-a7061845f4ee', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"How long is German B2?\",\"de\":\"Wie lange dauert Deutsch B2?\",\"ne\":\"जर्मन B2 कति लामो छ?\"}', '{\"en\":\"<p>German B2 runs for approximately 2.5 months with around two hours of classes per day.</p>\",\"de\":\"<p>Deutsch B2 dauert ungefähr 2,5 Monate, mit etwa zwei Unterrichtsstunden pro Tag.</p>\",\"ne\":\"<p>जर्मन B2 लगभग २.५ महिनाको हुन्छ, दिनमा लगभग दुई घण्टा कक्षा हुन्छन्।</p>\"}', NULL, NULL, 7, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-506d-73c7-bb9b-4de95a989a9f', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"Do you provide German exam preparation?\",\"de\":\"Bieten Sie Prüfungsvorbereitung für Deutsch an?\",\"ne\":\"तपाईंहरूले जर्मन परीक्षा तयारी दिनुहुन्छ?\"}', '{\"en\":\"<p>Yes. Exam-oriented preparation can include speaking, listening, reading, writing and mock-test exercises for A1–B2 learners.</p>\",\"de\":\"<p>Ja. Die prüfungsorientierte Vorbereitung kann Sprech-, Hör-, Lese- und Schreibübungen sowie Probetests für Lernende auf A1–B2 umfassen.</p>\",\"ne\":\"<p>हो। परीक्षामुखी तयारीमा A1–B2 सिकाइकर्ताहरूका लागि बोलाइ, सुनाइ, पढाइ, लेखाइ र मक-टेस्ट अभ्यासहरू समावेश हुन सक्छन्।</p>\"}', NULL, NULL, 8, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5071-7301-a315-82e2ef324a29', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"Do you provide Goethe exam preparation?\",\"de\":\"Bieten Sie eine Vorbereitung auf die Goethe-Prüfung an?\",\"ne\":\"तपाईंहरूले Goethe परीक्षाको तयारी दिनुहुन्छ?\"}', '{\"en\":\"<p>Students preparing for recognized German language examinations, including Goethe examinations, can contact us regarding preparation options.</p>\",\"de\":\"<p>Lernende, die sich auf anerkannte Deutschprüfungen wie die Goethe-Prüfungen vorbereiten, können uns zu den Vorbereitungsmöglichkeiten kontaktieren.</p>\",\"ne\":\"<p>Goethe परीक्षालगायत मान्यता प्राप्त जर्मन भाषा परीक्षाका लागि तयारी गर्ने सिकाइकर्ताहरूले तयारी विकल्पबारे हामीलाई सम्पर्क गर्न सक्छन्।</p>\"}', NULL, NULL, 9, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5074-72a1-83c4-c8dfa2709df3', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"Do you provide German classes for Ausbildung?\",\"de\":\"Bieten Sie Deutschkurse für die Ausbildung an?\",\"ne\":\"तपाईंहरूले Ausbildung का लागि जर्मन कक्षा दिनुहुन्छ?\"}', '{\"en\":\"<p>Yes. Learners preparing for Ausbildung can study progressively from German A1 through B1/B2 according to their individual requirements.</p>\",\"de\":\"<p>Ja. Lernende, die sich auf eine Ausbildung vorbereiten, können schrittweise von Deutsch A1 bis B1/B2 entsprechend ihren individuellen Anforderungen lernen.</p>\",\"ne\":\"<p>हो। Ausbildung को तयारी गर्ने सिकाइकर्ताहरूले आफ्ना व्यक्तिगत आवश्यकता अनुसार A1 देखि B1/B2 सम्म क्रमशः अध्ययन गर्न सक्छन्।</p>\"}', NULL, NULL, 10, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-5078-73ce-b933-ec707068e0bb', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"What German level is required for Ausbildung?\",\"de\":\"Welches Deutschniveau wird für die Ausbildung benötigt?\",\"ne\":\"Ausbildung का लागि कुन जर्मन स्तर चाहिन्छ?\"}', '{\"en\":\"<p>Requirements vary depending on the Ausbildung program, employer and other applicable conditions. Always verify the specific requirements of your intended program.</p>\",\"de\":\"<p>Die Anforderungen hängen vom Ausbildungsprogramm, vom Arbeitgeber und von weiteren geltenden Bedingungen ab. Prüfen Sie stets die konkreten Anforderungen des von Ihnen gewünschten Programms.</p>\",\"ne\":\"<p>आवश्यकताहरू Ausbildung कार्यक्रम, रोजगारदाता र अन्य लागू हुने सर्तहरूमा भर पर्छन्। तपाईंको इच्छित कार्यक्रमका विशिष्ट आवश्यकताहरू सधैं जाँच गर्नुहोस्।</p>\"}', NULL, NULL, 11, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-507c-7264-8c3d-0db4537986ee', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"Do you provide German speaking practice?\",\"de\":\"Bieten Sie Sprechtraining für Deutsch an?\",\"ne\":\"तपाईंहरूले जर्मन बोलाइ अभ्यास दिनुहुन्छ?\"}', '{\"en\":\"<p>Speaking and practical communication form an important part of our German language courses.</p>\",\"de\":\"<p>Sprechen und praktische Kommunikation sind ein wichtiger Bestandteil unserer Deutschkurse.</p>\",\"ne\":\"<p>बोलाइ र व्यावहारिक सञ्चार हाम्रा जर्मन भाषा कोर्सहरूको महत्त्वपूर्ण भाग हुन्।</p>\"}', NULL, NULL, 12, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fc1d-507f-7041-8909-2e1cb5ffb600', '01a0fc1d-5050-71a3-92bc-5a7ac3d25719', '{\"en\":\"Where are you located?\",\"de\":\"Wo befinden Sie sich?\",\"ne\":\"तपाईंहरूको ठेगाना कहाँ हो?\"}', '{\"en\":\"<p>We are located at Shrestha Tailoring Building / AC Complex, 4th Floor, Chabahil–7, Kathmandu, Nepal.</p>\",\"de\":\"<p>Wir befinden uns im Shrestha Tailoring Building / AC Complex, 4. Stock, Chabahil–7, Kathmandu, Nepal.</p>\",\"ne\":\"<p>हामी Shrestha Tailoring Building / AC Complex, ४ तल्ला, चावहिल–७, काठमाडौं, नेपालमा छौं।</p>\"}', NULL, NULL, 13, '2026-10-02 10:16:14', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a0fcad-47e1-719b-9ee2-279c5a936771', '01a0fc1d-4f5a-72e4-80be-8938ee0ed2a8', '{\"en\":\"4\",\"ne\":\"४\",\"de\":\"4\"}', '{\"en\":\"<p>German Language Levels</p>\",\"ne\":\"<p>जर्मन भाषा स्तरहरू</p>\",\"de\":\"<p>Deutsche Sprachniveaus</p>\"}', NULL, NULL, 0, '2026-10-02 12:53:29', '2026-10-03 16:25:28');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a10106-153e-7013-8d31-1db4681d355c', '01a0fc1d-4f54-73be-8bdc-f360c89a508e', '{\"en\":\"Learn German. Build Your Path to Germany.\",\"de\":\"Deutsch lernen. Ihren Weg nach Deutschland gestalten.\",\"ne\":\"जर्मन भाषा सिक्नुहोस्। जर्मनीतिर आफ्नो बाटो बनाउनुहोस्।\"}', '{\"en\":\"<p>Start your German language journey with Himalayan Education Pathways, your destination for structured German language classes in Chabahil, Kathmandu.</p><p>Learn German from A1 to B2 through practical lessons focused on speaking, listening, reading, writing, grammar and vocabulary.</p><p>Whether you\'re learning German for Ausbildung, higher education, career opportunities, examinations or life in Germany, start building your language skills with us.</p>\",\"de\":\"<p>Beginnen Sie Ihre Reise in die deutsche Sprache bei Himalayan Education Pathways, Ihrem Ort für strukturierte Deutschkurse in Chabahil, Kathmandu.</p><p>Lernen Sie Deutsch von A1 bis B2 in praxisnahen Lektionen, die sich auf Sprechen, Hören, Lesen, Schreiben, Grammatik und Wortschatz konzentrieren.</p><p>Ob Sie Deutsch für eine Ausbildung, ein Studium, berufliche Chancen, Prüfungen oder das Leben in Deutschland lernen – beginnen Sie mit uns, Ihre Sprachkenntnisse aufzubauen.</p>\",\"ne\":\"<p>Himalayan Education Pathways मार्फत आफ्नो जर्मन भाषा यात्रा सुरु गर्नुहोस्, जुन चावहिल, काठमाडौंमा व्यवस्थित जर्मन भाषा कक्षाहरूको गन्तव्य हो।</p><p>बोल्ने, सुन्ने, पढ्ने, लेख्ने, व्याकरण र शब्दावलीमा केन्द्रित व्यावहारिक कक्षाहरूमार्फत A1 देखि B2 सम्म जर्मन सिक्नुहोस्।</p><p>तपाईं Ausbildung, उच्च शिक्षा, करियर अवसर, परीक्षा वा जर्मनीमा जीवनका लागि जर्मन सिक्दै हुनुहुन्छ भने, हामीसँग आफ्नो भाषिक सीप निर्माण गर्न आजै सुरु गर्नुहोस्।</p>\"}', NULL, NULL, 0, '2026-10-03 09:08:58', '2026-10-04 06:21:30');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a10593-256c-719b-b823-bbcf74e20809', '01a0fc1d-4f54-73be-8bdc-f360c89a508e', '{\"en\":\"2\",\"de\":null}', '{\"en\":\"<p>Start your German language journey with Himalayan Education Pathways, your destination for structured German language classes in Chabahil, Kathmandu.</p><p>Learn German from A1 to B2 through practical lessons focused on speaking, listening, reading, writing, grammar and vocabulary.</p><p>Whether you\'re learning German for Ausbildung, higher education, career opportunities, examinations or life in Germany, start building your language skills with us.</p>\",\"de\":\"<p>Beginnen Sie Ihre Reise in die deutsche Sprache bei Himalayan Education Pathways, Ihrem Ort für strukturierte Deutschkurse in Chabahil, Kathmandu.</p><p>Lernen Sie Deutsch von A1 bis B2 in praxisnahen Lektionen, die sich auf Sprechen, Hören, Lesen, Schreiben, Grammatik und Wortschatz konzentrieren.</p><p>Ob Sie Deutsch für eine Ausbildung, ein Studium, berufliche Chancen, Prüfungen oder das Leben in Deutschland lernen – beginnen Sie mit uns, Ihre Sprachkenntnisse aufzubauen.</p>\",\"ne\":\"<p>Himalayan Education Pathways मार्फत आफ्नो जर्मन भाषा यात्रा सुरु गर्नुहोस्, जुन चावहिल, काठमाडौंमा व्यवस्थित जर्मन भाषा कक्षाहरूको गन्तव्य हो।</p><p>बोल्ने, सुन्ने, पढ्ने, लेख्ने, व्याकरण र शब्दावलीमा केन्द्रित व्यावहारिक कक्षाहरूमार्फत A1 देखि B2 सम्म जर्मन सिक्नुहोस्।</p><p>तपाईं Ausbildung, उच्च शिक्षा, करियर अवसर, परीक्षा वा जर्मनीमा जीवनका लागि जर्मन सिक्दै हुनुहुन्छ भने, हामीसँग आफ्नो भाषिक सीप निर्माण गर्न आजै सुरु गर्नुहोस्।</p>\"}', '2', NULL, 0, '2026-10-04 06:21:31', '2026-10-04 06:21:31');
INSERT INTO `section_items` (`id`, `section_id`, `title`, `description`, `icon_or_badge`, `link_url`, `sort_order`, `created_at`, `updated_at`) VALUES ('01a105a1-0ba1-70bd-8f71-1768f3cd6a08', '01a0fc1d-4f5a-72e4-80be-8938ee0ed2a8', '{\"en\":\"2\",\"de\":null}', '{\"en\":\"<p>German Language Levels</p>\",\"de\":\"<p>Deutsche Sprachniveaus</p>\",\"ne\":\"<p>जर्मन भाषा स्तरहरू</p>\"}', NULL, NULL, 0, '2026-10-04 06:36:42', '2026-10-04 06:36:42');
INSERT INTO `services` (`id`, `title`, `slug`, `summary`, `description`, `icon`, `fee`, `duration`, `is_featured`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-5084-73e3-97da-23fed31118fb', '{\"en\":\"German A1\",\"de\":null}', 'german-a1', '{\"en\":\"Build a strong foundation in German with essential vocabulary, basic grammar, pronunciation and everyday communication.\",\"de\":null}', '{\"en\":\"<h4>Overview</h4><p>German A1 develops the fundamental skills required to begin communicating in German. Students gradually learn how to introduce themselves, ask basic questions, understand simple conversations and communicate about common everyday topics.</p><h4>What You\'ll Learn</h4><p><br></p><h4>Skills Developed</h4><p><strong>Speaking:</strong> Introduce yourself and participate in simple everyday conversations.</p><p><strong>Listening:</strong> Understand basic expressions and slowly spoken German.</p><p><strong>Reading:</strong> Understand simple notices, messages and short texts.</p><p><strong>Writing:</strong> Write basic sentences, messages and personal information.</p>\",\"de\":null}', NULL, 12000, '2 Months', 1, 1, 1, '{\"en\":\"German A1 Classes in Kathmandu | A1 German Course Nepal\",\"de\":null}', '{\"en\":\"Join German A1 classes in Kathmandu at Himalayan Education Pathways. Learn beginner German grammar, vocabulary, speaking, listening, reading and writing.\",\"de\":null}', '{\"de\":null}', '2026-10-02 10:16:14', '2026-10-04 06:33:12', NULL);
INSERT INTO `services` (`id`, `title`, `slug`, `summary`, `description`, `icon`, `fee`, `duration`, `is_featured`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-508f-72b0-bcfa-2791fec69808', '{\"en\":\"German A2\"}', 'german-a2-classes-kathmandu', '{\"en\":\"Continue your German journey by expanding your vocabulary, grammar and communication skills for everyday situations.\"}', '{\"en\":\"<p>German A2 builds upon the foundation developed during A1. Students learn to communicate more confidently about familiar situations such as family, education, shopping, travel, work and daily activities.</p><h4>Key Learning Areas</h4><ul><li>Expanded vocabulary</li><li>A2 grammar</li><li>Everyday conversations</li><li>Describing experiences</li><li>Talking about past events</li><li>Travel situations</li><li>Work and education</li><li>Reading comprehension</li><li>Listening exercises</li><li>Structured writing</li><li>Speaking practice</li></ul>\"}', NULL, 14000, '2 Months', 1, 1, 2, NULL, NULL, NULL, '2026-10-02 10:16:14', '2026-10-02 10:16:14', NULL);
INSERT INTO `services` (`id`, `title`, `slug`, `summary`, `description`, `icon`, `fee`, `duration`, `is_featured`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-5093-7368-aefe-a7c87e400f3f', '{\"en\":\"German B1\"}', 'german-b1-classes-kathmandu', '{\"en\":\"Develop independent German communication skills through intermediate speaking, listening, reading, writing and grammar.\"}', '{\"en\":\"<p>German B1 helps learners become increasingly independent German users. Students develop the ability to communicate about familiar topics, describe experiences, explain plans and express opinions.</p><h4>Key Learning Areas</h4><ul><li>Intermediate German grammar</li><li>Expanded vocabulary</li><li>German conversations</li><li>Expressing opinions</li><li>Describing experiences</li><li>Reading longer texts</li><li>Listening comprehension</li><li>Structured writing</li><li>Speaking exercises</li><li>Exam-oriented activities</li></ul><p>B1 can be particularly relevant for learners developing German skills for Ausbildung, study, work or life in Germany.</p>\"}', NULL, 15000, '2.5 Months', 1, 1, 3, NULL, NULL, NULL, '2026-10-02 10:16:14', '2026-10-02 10:16:14', NULL);
INSERT INTO `services` (`id`, `title`, `slug`, `summary`, `description`, `icon`, `fee`, `duration`, `is_featured`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-5097-724b-a562-8e82563e144f', '{\"en\":\"German B2\"}', 'german-b2-classes-kathmandu', '{\"en\":\"Improve fluency, accuracy and confidence while developing advanced vocabulary, grammar and communication abilities.\"}', '{\"en\":\"<p>German B2 focuses on developing stronger fluency, accuracy and independent communication. Learners work with more complex vocabulary, grammar, texts and conversations.</p><h4>Key Learning Areas</h4><ul><li>Advanced grammar</li><li>Expanded vocabulary</li><li>Complex conversations</li><li>Expressing detailed opinions</li><li>Professional communication</li><li>Reading complex texts</li><li>Listening comprehension</li><li>Structured writing</li><li>Speaking fluency</li><li>Exam-oriented preparation</li></ul>\"}', NULL, 25000, '2.5 Months', 1, 1, 4, NULL, NULL, NULL, '2026-10-02 10:16:14', '2026-10-02 10:16:14', NULL);
INSERT INTO `services` (`id`, `title`, `slug`, `summary`, `description`, `icon`, `fee`, `duration`, `is_featured`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-509c-72e9-a603-444ef782857f', '{\"en\":\"German Exam Preparation\"}', 'german-exam-preparation-kathmandu', '{\"en\":\"Prepare across speaking, listening, reading and writing with exam-oriented exercises and mock-test activities.\"}', '{\"en\":\"<p>Preparing for a German language examination requires both language knowledge and familiarity with exam-style activities. Our exam preparation focuses on developing confidence across the four major language skills.</p><p><strong>Speaking:</strong> Practice structured conversations, pronunciation and responding to common speaking tasks.</p><p><strong>Listening:</strong> Develop strategies for understanding spoken German and identifying important information.</p><p><strong>Reading:</strong> Improve comprehension of German texts, notices, messages and longer passages.</p><p><strong>Writing:</strong> Practice structured German writing appropriate to your language level.</p><p><strong>Mock Test Practice:</strong> Work with exam-oriented exercises to identify areas that need improvement.</p><h4>Available Levels</h4><ul><li>A1 Exam Preparation</li><li>A2 Exam Preparation</li><li>B1 Exam Preparation</li><li>B2 Exam Preparation</li></ul><p><em>Himalayan Education Pathways provides German language and exam preparation. Unless formally authorized, the institute should not be presented as an official Goethe examination center.</em></p>\"}', NULL, NULL, NULL, 0, 1, 5, '{\"en\":\"German Exam Preparation Kathmandu | A1 A2 B1 B2\"}', NULL, NULL, '2026-10-02 10:16:14', '2026-10-02 10:16:14', NULL);
INSERT INTO `services` (`id`, `title`, `slug`, `summary`, `description`, `icon`, `fee`, `duration`, `is_featured`, `is_active`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-50a1-714e-8bd3-bcd5a122804c', '{\"en\":\"German for Ausbildung\"}', 'german-language-for-ausbildung-nepal', '{\"en\":\"Build German communication skills progressively from A1 toward the language level appropriate for your individual Ausbildung pathway.\"}', '{\"en\":\"<p>Planning to pursue vocational training in Germany? Developing German communication skills is an important part of preparing for Ausbildung and everyday life in Germany. Himalayan Education Pathways provides structured German courses from A1 through B2 for learners preparing for their future in Germany.</p><h4>Build Your German Step by Step</h4><p><strong>A1:</strong> Build your German foundation.</p><p><strong>A2:</strong> Become more confident in everyday communication.</p><p><strong>B1:</strong> Develop independent German communication.</p><p><strong>B2:</strong> Strengthen fluency for more complex situations.</p><h4>What You\'ll Develop</h4><ul><li>Everyday German communication</li><li>Speaking confidence</li><li>Listening comprehension</li><li>Grammar</li><li>Vocabulary</li><li>Reading</li><li>Writing</li><li>Practical German communication</li></ul><p><em>Language requirements differ between Ausbildung programs, employers and circumstances. Students should verify the requirements applicable to their individual pathway.</em></p>\"}', NULL, NULL, NULL, 0, 1, 6, '{\"en\":\"German Language for Ausbildung Nepal | German Classes Kathmandu\"}', NULL, NULL, '2026-10-02 10:16:14', '2026-10-02 10:16:14', NULL);
INSERT INTO `posts` (`id`, `type`, `title`, `slug`, `summary`, `content`, `is_featured`, `status`, `published_at`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-50a9-7316-a577-fcd5e312d50a', 'post', '{\"en\":\"How to Learn German A1 in Nepal: A Beginner\'s Guide\",\"ne\":\"नेपालमा जर्मन A1 कसरी सिक्ने: शुरुवातीका लागि मार्गदर्शक\",\"de\":\"Deutsch A1 in Nepal lernen: Ein Leitfaden für Anfänger\"}', 'how-to-learn-german-a1-in-nepal-a-beginners-guide', '{\"en\":\"Starting German for the first time? Learn what A1 covers and how to build a strong foundation in grammar, vocabulary, speaking and listening.\",\"ne\":\"पहिलो पटक जर्मन सुरु गर्दै हुनुहुन्छ? A1 ले के समेट्छ र व्याकरण, शब्दावली, बोलाइ र सुनाइमा बलियो आधार कसरी निर्माण गर्ने भनेर जानुहोस्।\",\"de\":\"Zum ersten Mal Deutsch lernen? Erfahren Sie, was A1 umfasst und wie Sie eine solide Grundlage in Grammatik, Wortschatz, Sprechen und Hören aufbauen.\"}', '{\"en\":\"<p>German A1 is the starting point for learners beginning their German language journey. Whether you\'re learning German for Ausbildung, education, professional opportunities, travel or future plans in Germany, developing a strong A1 foundation can make progression to higher levels much easier.</p><h3>What Is German A1?</h3><p>A1 is the beginner level within the Common European Framework of Reference for Languages (CEFR). At this stage, learners begin developing the ability to understand and use simple German expressions related to familiar everyday situations.</p><h3>What Do You Learn in German A1?</h3><p>Typical topics include:</p><p><br></p><p>Students also begin learning essential German grammar and sentence structures.</p><h3>Develop All Four Language Skills</h3><p><strong>Speaking:</strong> Practice introducing yourself, asking questions and responding in simple conversations.</p><p><strong>Listening:</strong> Become familiar with common German expressions and basic spoken conversations.</p><p><strong>Reading:</strong> Learn to understand simple German notices, messages and short texts.</p><p><strong>Writing:</strong> Practice writing basic sentences, messages and personal information.</p><h3>Learn Vocabulary in Context</h3><p>Instead of memorizing isolated words, learn vocabulary around topics such as family, food, travel and daily activities. This makes vocabulary easier to recall when speaking and writing.</p><h3>Practice German Every Day</h3><p>Consistency is important when learning a new language. Even short daily activities can help:</p><p><br></p><h3>Take Structured German Classes</h3><p>Structured classes provide learners with a clear progression and regular opportunities to practice German. Students looking for German A1 classes in Kathmandu can begin their learning journey at Himalayan Education Pathways in Chabahil.</p>\",\"de\":\"<p>Deutsch A1 ist der Ausgangspunkt für Lernende, die ihre Deutschreise beginnen. Ob Sie Deutsch für eine Ausbildung, Bildung, berufliche Chancen, Reisen oder Zukunftspläne in Deutschland lernen – eine solide A1-Grundlage erleichtert den Fortschritt auf höhere Niveaus erheblich.</p><h3>Was ist Deutsch A1?</h3><p>A1 ist die Anfängerstufe im Gemeinsamen Europäischen Referenzrahmen für Sprachen (GER). Auf dieser Stufe beginnen Lernende, einfache deutsche Ausdrücke aus vertrauten Alltagssituationen zu verstehen und zu verwenden.</p><h3>Was lernen Sie in Deutsch A1?</h3><p>Typische Themen sind:</p><p><br></p><p>Außerdem lernen die Studierenden grundlegende deutsche Grammatik und Satzstrukturen.</p><h3>Alle vier Sprachfertigkeiten entwickeln</h3><p><strong>Sprechen:</strong> Üben Sie, sich vorzustellen, Fragen zu stellen und in einfachen Gesprächen zu antworten.</p><p><strong>Hören:</strong> Machen Sie sich mit gängigen deutschen Ausdrücken und einfachen gesprochenen Gesprächen vertraut.</p><p><strong>Lesen:</strong> Lernen Sie, einfache deutsche Hinweise, Nachrichten und kurze Texte zu verstehen.</p><p><strong>Schreiben:</strong> Üben Sie, einfache Sätze, Nachrichten und persönliche Angaben zu schreiben.</p><h3>Wortschatz im Kontext lernen</h3><p>Statt isolierte Wörter auswendig zu lernen, lernen Sie Vokabeln rund um Themen wie Familie, Essen, Reisen und Alltagsaktivitäten. So fällt es leichter, sich beim Sprechen und Schreiben daran zu erinnern.</p><h3>Jeden Tag Deutsch üben</h3><p>Beständigkeit ist wichtig, wenn man eine neue Sprache lernt. Schon kurze tägliche Übungen können helfen:</p><p><br></p><h3>Strukturierte Deutschkurse besuchen</h3><p>Strukturierte Kurse bieten Lernenden einen klaren Fortschritt und regelmäßige Gelegenheiten, Deutsch zu üben. Studierende, die Deutsch-A1-Kurse in Kathmandu suchen, können ihre Lernreise bei Himalayan Education Pathways in Chabahil beginnen.</p>\",\"ne\":\"<p>जर्मन A1 जर्मन भाषा यात्रा सुरु गर्ने सिकाइकर्ताहरूका लागि सुरुवाती बिन्दु हो। तपाईं Ausbildung, शिक्षा, व्यावसायिक अवसर, यात्रा वा जर्मनीमा भविष्यका योजनाका लागि जर्मन सिक्दै हुनुहुन्छ भने पनि, बलियो A1 आधारले उच्च स्तरमा प्रगति गर्न धेरै सजिलो बनाउँछ।</p><h3>जर्मन A1 भनेको के हो?</h3><p>A1 भाषा सिकाइका लागि युरोपेली साझा सन्दर्भ ढाँचा (CEFR) भित्रको शुरुवाती तह हो। यस चरणमा सिकाइकर्ताहरूले परिचित दैनिक परिस्थितिसँग सम्बन्धित सरल जर्मन अभिव्यक्ति बुझ्ने र प्रयोग गर्ने क्षमता विकास गर्न थाल्छन्।</p><h3>जर्मन A1 मा के सिकिन्छ?</h3><p>सामान्य विषयहरू यस प्रकार छन्:</p><p><br></p><p>विद्यार्थीहरूले आवश्यक जर्मन व्याकरण र वाक्य संरचना पनि सिक्न थाल्छन्।</p><h3>चारै भाषिक सीप विकास गर्नुहोस्</h3><p><strong>बोलाइ:</strong> आफ्नो परिचय दिने, प्रश्न सोध्ने र सरल संवादमा जवाफ दिने अभ्यास गर्नुहोस्।</p><p><strong>सुनाइ:</strong> सामान्य जर्मन अभिव्यक्ति र आधारभूत बोलिएका संवादसँग परिचित हुनुहोस्।</p><p><strong>पढाइ:</strong> सरल जर्मन सूचना, सन्देश र छोटा पाठहरू बुझ्न सिक्नुहोस्।</p><p><strong>लेखाइ:</strong> आधारभूत वाक्य, सन्देश र व्यक्तिगत विवरण लेख्ने अभ्यास गर्नुहोस्।</p><h3>सन्दर्भसहित शब्दावली सिक्नुहोस्</h3><p>छुट्टाछुट्टै शब्द कण्ठ गर्नुको सट्टा परिवार, खाना, यात्रा र दैनिक क्रियाकलाप जस्ता विषयका वरिपरिका शब्दावली सिक्नुहोस्। यसले बोल्दा र लेख्दा शब्दहरू सम्झन सजिलो बनाउँछ।</p><h3>हरेक दिन जर्मन अभ्यास गर्नुहोस्</h3><p>नयाँ भाषा सिक्दा निरन्तरता महत्त्वपूर्ण हुन्छ। छोटा दैनिक क्रियाकलापहरूले पनि मद्दत गर्न सक्छन्:</p><p><br></p><h3>व्यवस्थित जर्मन कक्षा लिनुहोस्</h3><p>व्यवस्थित कक्षाहरूले सिकाइकर्ताहरूलाई स्पष्ट प्रगति र जर्मन अभ्यास गर्ने नियमित अवसर दिन्छन्। काठमाडौंमा जर्मन A1 कक्षा खोज्ने विद्यार्थीहरूले चावहिलस्थित Himalayan Education Pathways बाट आफ्नो सिकाइ यात्रा सुरु गर्न सक्छन्।</p>\"}', 0, 'published', '2026-09-05 10:16:00', 1, '{\"en\":\"How to Learn German A1 in Nepal | Beginner\'s Guide\",\"de\":\"Deutsch A1 in Nepal lernen | Leitfaden für Anfänger\",\"ne\":\"नेपालमा जर्मन A1 कसरी सिक्ने | शुरुवाती गाइड\"}', '{\"en\":\"Learn how to start German A1 in Nepal, including vocabulary, grammar, speaking, listening, reading and effective beginner study strategies.\",\"de\":\"Erfahren Sie, wie Sie in Nepal mit Deutsch A1 beginnen, einschließlich Wortschatz, Grammatik, Sprechen, Hören, Lesen und wirksamen Lernstrategien für Anfänger.\",\"ne\":\"नेपालमा जर्मन A1 कसरी सुरु गर्ने भनेर जानुहोस्, जसमा शब्दावली, व्याकरण, बोलाइ, सुनाइ, पढाइ र प्रभावकारी शुरुवाती अध्ययन रणनीतिहरू समावेश छन्।\"}', '{\"de\":null}', '2026-10-02 10:16:14', '2026-10-02 12:35:28', NULL);
INSERT INTO `posts` (`id`, `type`, `title`, `slug`, `summary`, `content`, `is_featured`, `status`, `published_at`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-50af-70c5-a754-9f1539322d63', 'post', '{\"en\":\"German A1 Exam: Complete Preparation Guide\",\"de\":\"Deutsch-A1-Prüfung: Vollständiger Vorbereitungsleitfaden\",\"ne\":\"जर्मन A1 परीक्षा: पूर्ण तयारी गाइड\"}', 'german-a1-exam-guide', '{\"en\":\"Understand the key skills involved in A1-level German examinations and how to prepare speaking, listening, reading and writing.\",\"de\":\"Verstehen Sie die wichtigsten Fertigkeiten, die bei Deutschprüfungen auf A1-Niveau gefordert werden, und wie Sie sich auf Sprechen, Hören, Lesen und Schreiben vorbereiten.\",\"ne\":\"A1 स्तरको जर्मन परीक्षामा आवश्यक मुख्य सीपहरू बुझ्नुहोस् र बोलाइ, सुनाइ, पढाइ र लेखाइको तयारी कसरी गर्ने भनेर जानुहोस्।\"}', '{\"en\":\"Understand the key skills involved in A1-level German examinations and how to prepare speaking, listening, reading and writing.\",\"de\":\"Verstehen Sie die wichtigsten Fertigkeiten, die bei Deutschprüfungen auf A1-Niveau gefordert werden, und wie Sie sich auf Sprechen, Hören, Lesen und Schreiben vorbereiten.\",\"ne\":\"A1 स्तरको जर्मन परीक्षामा आवश्यक मुख्य सीपहरू बुझ्नुहोस् र बोलाइ, सुनाइ, पढाइ र लेखाइको तयारी कसरी गर्ने भनेर जानुहोस्।\"}', 0, 'published', '2026-09-08 10:16:14', 2, NULL, NULL, NULL, '2026-10-02 10:16:14', '2026-10-02 10:16:14', NULL);
INSERT INTO `posts` (`id`, `type`, `title`, `slug`, `summary`, `content`, `is_featured`, `status`, `published_at`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`, `deleted_at`) VALUES ('01a0fc1d-50b3-728b-932a-b032fa64f8a5', 'post', '{\"en\":\"German A1 vs A2: What\'s the Difference?\",\"de\":\"Deutsch A1 vs. A2: Was ist der Unterschied?\",\"ne\":\"जर्मन A1 बनाम A2: फरक के हो?\"}', 'german-a1-vs-a2', '{\"en\":\"Understand the differences between A1 and A2 German, including vocabulary, grammar and communication expectations.\",\"de\":\"Verstehen Sie die Unterschiede zwischen Deutsch A1 und A2, einschließlich Wortschatz, Grammatik und Anforderungen an die Kommunikation.\",\"ne\":\"A1 र A2 जर्मनबीचका फरकहरू बुझ्नुहोस्, जसमा शब्दावली, व्याकरण र सञ्चार अपेक्षाहरू समावेश छन्।\"}', '{\"en\":\"Understand the differences between A1 and A2 German, including vocabulary, grammar and communication expectations.\",\"de\":\"Verstehen Sie die Unterschiede zwischen Deutsch A1 und A2, einschließlich Wortschatz, Grammatik und Anforderungen an die Kommunikation.\",\"ne\":\"A1 र A2 जर्मनबीचका फरकहरू बुझ्नुहोस्, जसमा शब्दावली, व्याकरण र सञ्चार अपेक्षाहरू समावेश छन्।\"}', 0, 'published', '2026-09-11 10:16:14', 3, NULL, NULL, NULL, '2026-10-02 10:16:14', '2026-10-02 10:16:14', NULL);
